def test_configure_axis_domain_min_max_overrides_data():
    """configure_axis(domain_min=, domain_max=) should override the data domain.

    Targets chart.py:4458-4459 -> configure.py:AxisConfig.domain_min/domain_max.
    The resulting SVG should show ticks only within the overridden domain.
    """
    df = pl.DataFrame({"x": [0.0, 5.0, 10.0], "y": [1.0, 2.0, 3.0]})
    svg = (
        fr.Chart(df)
        .mark_point()
        .encode(x="x", y="y")
        .configure_axis(domain_min=2.0, domain_max=8.0)
        .to_svg()
    )
    assert "<svg" in svg
    assert "NaN" not in svg
    assert "Infinity" not in svg


