# TimeScale edge cases
# ---------------------------------------------------------------------------


def test_time_scale_zero_span_domain():
    """TimeScale with domain [t, t] (zero span) should reject with ValueError.

    Targets core.rs:validate_continuous_pair — domain endpoints must differ.
    """
    t = 1_767_225_600_000.0  # 2026-01-01 00:00:00 UTC
    with pytest.raises(ValueError, match="domain endpoints must differ"):
        fr.TimeScale(domain=[t, t], range=[0.0, 1000.0])


def test_time_scale_reversed_domain():
    """TimeScale with domain [t_hi, t_lo] (reversed) should still work.

    The linear mapping is valid for reversed domains with clamp=True.
    """
    t_lo = 1_767_225_600_000.0
    t_hi = 1_798_761_599_000.0
    s = fr.TimeScale(domain=[t_hi, t_lo], range=[0.0, 1000.0], clamp=True)
    # At t_hi (start of domain), should map to range[0]=0.0
    assert math.isclose(s.scale(t_hi), 0.0)
    # At t_lo (end of domain), should map to range[1]=1000.0
    assert math.isclose(s.scale(t_lo), 1000.0)


def test_time_scale_ticks_zero_count():
    """TimeScale.ticks(0) should return an empty list.

    Targets ticks.rs:calendar_ticks — count==0 guard at line 151.
    """
    s = fr.TimeScale(domain=[1_767_225_600_000.0, 1_798_761_599_000.0], range=[0.0, 1000.0])
    t = s.ticks(0)
    assert t == []


def test_time_scale_nice_snaps_to_calendar():
    """TimeScale.nice() should snap domain endpoints to calendar boundaries."""
    t_lo = 1_767_225_600_000.0 + 12345.0  # offset from Jan 1
    t_hi = 1_798_761_599_000.0 - 12345.0  # offset from Dec 31
    s = fr.TimeScale(domain=[t_lo, t_hi], range=[0.0, 1000.0], nice=True)
    # After nicing, domain[0] should be <= t_lo and domain[1] >= t_hi
    assert s.domain[0] <= t_lo
    assert s.domain[1] >= t_hi


