def test_band_scale_single_category():
    """BandScale with a single category should produce a non-zero bandwidth.

    Targets band.rs:layout() — n=1, denom = max(1, 1 - pi + po*2).
    """
    s = fr.BandScale(domain=["only"], range=[0.0, 300.0])
    bw = s.bandwidth()
    assert bw > 0.0, f"single category should have positive bandwidth, got {bw}"
    assert math.isfinite(bw)


def test_band_scale_many_categories():
    """BandScale with 100 categories should produce small but valid bandwidths."""
    cats = [f"c{i}" for i in range(100)]
    s = fr.BandScale(domain=cats, range=[0.0, 1000.0])
    bw = s.bandwidth()
    assert bw > 0.0
    assert bw < 20.0  # 1000 / 100 = 10, with padding ~8


def test_band_scale_unknown_category_returns_nan():
    """BandScale.scale('unknown') should return NaN.

    Targets band.rs:scale_str line 27-29.
    """
    s = fr.BandScale(domain=["a", "b", "c"], range=[0.0, 300.0])
    result = s.scale("unknown")
    assert math.isnan(result)


