# ---------------------------------------------------------------------------
# QuantizeScale edge cases
# ---------------------------------------------------------------------------


def test_quantize_scale_reversed_domain():
    """QuantizeScale with domain [hi, lo] (reversed) should still bin correctly.

    Targets quantize.rs line 21: t = (x - d0) / (d1 - d0) with d0 > d1.
    The normalization inverts, so x near d0 maps to the first bin and
    x near d1 maps to the last.
    """
    s = fr.QuantizeScale(domain=[100.0, 0.0], range=["high", "mid", "low"])
    # x=90 is near d0=100, so t = (90-100)/(0-100) = 0.1, bin index 0
    assert s.scale(90.0) == "high"
    # x=10 is near d1=0, so t = (10-100)/(0-100) = 0.9, bin index 2
    assert s.scale(10.0) == "low"


def test_quantize_scale_single_bin():
    """QuantizeScale with a single range value maps everything to that value."""
    s = fr.QuantizeScale(domain=[0.0, 100.0], range=["only"])
    assert s.scale(0.0) == "only"
    assert s.scale(50.0) == "only"
    assert s.scale(100.0) == "only"
    assert s.scale(-100.0) == "only"
    assert s.scale(200.0) == "only"


def test_quantize_scale_thresholds_single_bin():
    """QuantizeScale with 1 range value should have 0 thresholds."""
    s = fr.QuantizeScale(domain=[0.0, 100.0], range=["only"])
    assert s.thresholds() == []


