def test_bin_ordinal_scale_single_edge():
    """BinOrdinalScale with 1 bin edge should produce 2 output bins."""
    s = fr.BinOrdinalScale(bins=[50.0])
    assert s.num_bins == 2
    assert s.scale(10.0) == 0
    assert s.scale(50.0) == 1
