def test_linear_scale_nice_very_small_domain():
    """LinearScale.nice() with very small domain span should not infinite-loop.

    Domain [1e-10, 2e-10]: nice_step should produce a reasonable step.
    """
    s = fr.LinearScale(domain=[1e-10, 2e-10], range=[0.0, 1.0], nice=True)
    d = s.domain
    assert d[0] <= 1e-10
    assert d[1] >= 2e-10
    assert not math.isnan(d[0])
    assert not math.isnan(d[1])


def test_linear_scale_nice_negative_domain():
    """LinearScale.nice() with all-negative domain should expand outward."""
    s = fr.LinearScale(domain=[-9.7, -0.13], range=[0.0, 1.0], nice=True)
    d = s.domain
    assert d[0] <= -9.7
    assert d[1] >= -0.13


def test_linear_scale_ticks_count_one():
    """LinearScale.ticks(1) should return at most a few ticks."""
    s = fr.LinearScale(domain=[0.0, 100.0], range=[0.0, 1.0])
    t = s.ticks(1)
    # With count=1, nice_step picks a large step; few ticks expected
    assert len(t) >= 1


def test_linear_scale_ticks_count_zero():
    """LinearScale.ticks(0) should return an empty list.

    Targets ticks.rs:nice_ticks count==0 guard at line 36.
    """
    s = fr.LinearScale(domain=[0.0, 100.0], range=[0.0, 1.0])
    t = s.ticks(0)
    assert t == []


def test_linear_scale_ticks_very_large_count():
    """LinearScale.ticks(10000) should not crash or produce unreasonable output."""
    s = fr.LinearScale(domain=[0.0, 10.0], range=[0.0, 1.0])
    t = s.ticks(10000)
    # Should produce a reasonable number of ticks (not 10000)
    assert len(t) > 0
    assert len(t) < 100000  # sanity bound


# ---------------------------------------------------------------------------
# LogScale edge cases
# ---------------------------------------------------------------------------


def test_log_scale_base_2():
    """LogScale with base=2 should map correctly.

    Targets log.rs: custom base handling in log_base = self.base.ln().
    """
    s = fr.LogScale(domain=[1.0, 16.0], range=[0.0, 4.0], base=2.0)
    # log2(1) = 0, log2(16) = 4; log2(8) = 3, so 8 should map to 3.0
    assert math.isclose(s.scale(8.0), 3.0, abs_tol=1e-9)
    # Round-trip
    back = s.invert(3.0)
    assert math.isclose(back, 8.0, abs_tol=1e-6)


def test_log_scale_base_e():
    """LogScale with base=e should use natural logarithm."""
    import math as m

    s = fr.LogScale(domain=[1.0, m.e**3], range=[0.0, 3.0], base=m.e)
    assert math.isclose(s.scale(m.e), 1.0, abs_tol=1e-9)
    assert math.isclose(s.scale(m.e**2), 2.0, abs_tol=1e-9)


def test_log_scale_ticks_single_decade():
    """LogScale ticks for a sub-decade domain [1, 5] should produce ticks."""
    s = fr.LogScale(domain=[1.0, 5.0], range=[0.0, 1.0])
    t = s.ticks(5)
    assert len(t) > 0
    for v in t:
        assert math.isfinite(v), f"tick contains non-finite value: {v}"


def test_log_scale_ticks_many_decades():
    """LogScale ticks for a multi-decade domain [1e-3, 1e6] should work."""
    s = fr.LogScale(domain=[1e-3, 1e6], range=[0.0, 9.0])
    t = s.ticks(10)
    assert len(t) > 0
    # Should include powers of 10
    # All ticks should be positive
    for v in t:
        assert v > 0, f"log scale tick should be positive: {v}"


def test_log_scale_negative_domain_nice():  # BUG: nice() inverts domain for negative log scales — d[0]=-1 instead of -1000
    """LogScale.nice() with negative domain should round to powers of base.

    Targets log.rs:nice() line 95-99. With domain=[-700, -3], sign=-1.
    After nicing: lo=abs(-3)=3, hi=abs(-700)=700.
    lo_exp = floor(log10(3)) = 0, hi_exp = ceil(log10(700)) = 3.
    new_lo = -1 * 10^0 = -1, new_hi = -1 * 10^3 = -1000.
    Since d[0]=-700 <= d[1]=-3, it sets domain = [new_lo, new_hi] = [-1, -1000].
    BUG: The niced domain is [-1, -1000] which inverts the original direction.
    Expected: [-1000, -1] (lo is the more-negative endpoint).
    """
    s = fr.LogScale(domain=[-700.0, -3.0], range=[0.0, 1.0], nice=True)
    d = s.domain
    # d[0] should be a power of 10 <= -700 (i.e. -1000)
    # d[1] should be a power of 10 >= -3 (i.e. -1)
    assert d[0] <= -700.0, f"nice lo: {d[0]}"
    assert d[1] >= -3.0, f"nice hi: {d[1]}"


# ---------------------------------------------------------------------------
# SymlogScale edge cases
# ---------------------------------------------------------------------------


def test_symlog_scale_very_large_constant():
    """SymlogScale with very large constant should approximate linear scale.

    When constant >> |domain|, the transform is nearly linear.
    """
    s = fr.SymlogScale(domain=[-10.0, 10.0], range=[0.0, 1.0], constant=1e10)
    # Near-linear: scale(5) should be close to 0.75 (midpoint + half)
    y = s.scale(5.0)
    assert math.isclose(y, 0.75, abs_tol=0.01), f"expected ~0.75, got {y}"


def test_symlog_scale_very_small_constant():
    """SymlogScale with very small constant should approximate log scale.

    When constant << |domain|, the transform is nearly logarithmic.
    """
    s = fr.SymlogScale(domain=[-100.0, 100.0], range=[0.0, 1.0], constant=0.001)
    # With a tiny constant, the scale is highly logarithmic
    y = s.scale(50.0)
    assert y > 0.5  # compressed toward endpoint
    assert y < 1.0


def test_symlog_scale_domain_spanning_zero():
    """SymlogScale with domain [-1, 1] and constant=1 should be symmetric."""
    s = fr.SymlogScale(domain=[-1.0, 1.0], range=[0.0, 1.0], constant=1.0)
    y_neg = s.scale(-0.5)
    y_pos = s.scale(0.5)
    # By symmetry, y_neg + y_pos should equal 1.0
    assert math.isclose(y_neg + y_pos, 1.0, abs_tol=1e-9), (
        f"expected y(-0.5) + y(0.5) = 1.0, got {y_neg} + {y_pos} = {y_neg + y_pos}"
    )


# ---------------------------------------------------------------------------
# PowScale edge cases
# ---------------------------------------------------------------------------


def test_pow_scale_exponent_one_is_linear():
    """PowScale with exponent=1 should behave identically to LinearScale.

    Targets pow.rs: pow_fwd(v) = v.signum() * v.abs().powf(1.0) = v.
    """
    p = fr.PowScale(domain=[0.0, 100.0], range=[0.0, 1.0], exponent=1.0)
    l = fr.LinearScale(domain=[0.0, 100.0], range=[0.0, 1.0])
    for x in [0.0, 25.0, 50.0, 75.0, 100.0]:
        assert math.isclose(p.scale(x), l.scale(x), abs_tol=1e-12), (
            f"PowScale(exp=1) should match Linear at x={x}"
        )


def test_pow_scale_negative_domain_with_fractional_exponent():
    """PowScale with negative domain and fractional exponent.

    Targets pow.rs:pow_fwd — v.signum() * v.abs().powf(exp) handles negatives.
    """
    p = fr.PowScale(domain=[-100.0, 100.0], range=[0.0, 1.0], exponent=0.5)
    y_neg = p.scale(-50.0)
    y_pos = p.scale(50.0)
    # Both should be finite and in [0, 1]
    assert math.isfinite(y_neg)
    assert math.isfinite(y_pos)
    # Symmetry: y(-50) + y(50) should be close to 1.0
    # since pow_fwd(-50) = -sqrt(50), pow_fwd(50) = sqrt(50)


def test_sqrt_scale_domain_includes_zero():
    """SqrtScale with domain starting at 0 should handle x=0 correctly."""
    s = fr.SqrtScale(domain=[0.0, 100.0], range=[0.0, 1.0])
    assert s.scale(0.0) == 0.0
    assert math.isclose(s.scale(25.0), 0.5, abs_tol=1e-12)
    assert s.scale(100.0) == 1.0


